def svg(name, cls='icon', extra=''):
    p = ICONS.get(name)
    if p is None:
        raise KeyError('unknown icon: ' + name)
    return f'<svg class="{cls}" viewBox="0 0 24 24" aria-hidden="true"{extra}>{p}</svg>'

